CREATE ROLE authenticated; CREATE ROLE anon; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.uid',true),'')::uuid $$;
CREATE FUNCTION public.current_empresa_id() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.tenant',true),'')::uuid $$;
CREATE FUNCTION public.is_empresa_member(t uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT t=public.current_empresa_id() AND auth.uid() IS NOT NULL $$;
CREATE FUNCTION public.current_user_is_client_scoped(t uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce(current_setting('test.client',true),'false')='true' $$;
CREATE FUNCTION public.current_user_has_permission(t uuid,p text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT t=public.current_empresa_id() AND p=ANY(string_to_array(current_setting('test.permissions',true),',')) $$;
CREATE TABLE empresas(id uuid PRIMARY KEY DEFAULT gen_random_uuid());
CREATE TABLE clientes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid REFERENCES empresas,nome text);
CREATE TABLE configuracoes_contas_bancarias(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid REFERENCES empresas,banco text,agencia text,numero_conta text,tipo_conta text,saldo_inicial numeric(15,2) DEFAULT 0,saldo_atual numeric(15,2) DEFAULT 0,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE financeiro_lancamentos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid REFERENCES empresas,conta_bancaria_id uuid REFERENCES configuracoes_contas_bancarias,cliente_empresa_id uuid REFERENCES clientes ON DELETE SET NULL,tipo text,origem text,descricao text,categoria text,valor numeric(15,2),data_competencia date,data_pagamento date,status text,referencia_id uuid,metadados jsonb DEFAULT '{}',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE financeiro_cobrancas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid REFERENCES empresas,cliente_empresa_id uuid REFERENCES clientes ON DELETE SET NULL,valor numeric(15,2),status text,data_vencimento date,data_pagamento timestamptz,descricao text,categoria text,updated_at timestamptz DEFAULT now());
CREATE TABLE financeiro_cobrancas_integracoes(empresa_id uuid,cobranca_id uuid,provedor text);
ALTER TABLE financeiro_lancamentos ENABLE ROW LEVEL SECURITY;
ALTER TABLE configuracoes_contas_bancarias ENABLE ROW LEVEL SECURITY;
ALTER TABLE financeiro_cobrancas ENABLE ROW LEVEL SECURITY;
ALTER TABLE clientes ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant ON financeiro_lancamentos FOR ALL TO authenticated USING (is_empresa_member(empresa_id) AND NOT current_user_is_client_scoped(empresa_id)) WITH CHECK (is_empresa_member(empresa_id));
CREATE POLICY tenant ON configuracoes_contas_bancarias FOR ALL TO authenticated USING (is_empresa_member(empresa_id) AND NOT current_user_is_client_scoped(empresa_id)) WITH CHECK (is_empresa_member(empresa_id));
CREATE POLICY tenant ON financeiro_cobrancas FOR ALL TO authenticated USING (is_empresa_member(empresa_id));
CREATE POLICY tenant ON clientes FOR ALL TO authenticated USING (is_empresa_member(empresa_id));
GRANT USAGE ON SCHEMA public,auth TO authenticated,anon,service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated,service_role;
